    Given a set $P \subset \ensuremath{\mathbb{R}}^d$ of $n$ points and $\ensuremath{\varepsilon} \in (0,1)$, an $\ensuremath{\varepsilon}$-coreset is a set $\Omega = \{q_1, \ldots, q_m\} \subset \ensuremath{\mathbb{R}}^d$ of points with weights $\{w_{q_1}, \ldots, w_{q_m}\}$, that for any set of $k$ centers $S\in \mathcal{S}$ approximately preserves the $k$-means objective of $P$ with respect to $S$, i.e., 
    \begin{align*}
        \textnormal{cost}_\Omega(P,S) \in  (1\pm \ensuremath{\varepsilon}) \textnormal{cost}(P,S).
    \end{align*}
The number of points $m$ in the coreset is called its \emph{size}.

\begin{align*}
        \textnormal{cost}_\Omega(P,S) \in  (1\pm \ensuremath{\varepsilon}) \textnormal{cost}(P,S).
    \end{align*}

\begin{align}\label{eq: goal}
	\begin{split}
		\mathop{\mathbb{E}}_{ \Omega} \sup_{S \in \mathcal{S}} \left\lvert \frac{\textnormal{cost}(P,S) - \textnormal{cost}_\Omega(P,S)}{\textnormal{cost}(P,S) } \right\rvert \leq \ensuremath{\varepsilon}.
	\end{split}
\end{align}

\begin{align}\label{eq: roadmap-sym}
\mathop{\mathbb{E}}_{ \Omega} \mathop{\mathbb{E}}_{g} \sup_{S \in \mathcal{S}} \left\lvert \frac{\sum_{q_i \in \Omega}g_i \cdot w_{q_i} \cdot \textnormal{cost}(q_i,S) }{\textnormal{cost}(P,S)} \right\rvert  \leq \ensuremath{\varepsilon},
\end{align}

