Let $\Omega = \{q_1, \ldots, q_m\}$ be the set of $m$ points sampled by \Cref{alg: sensitivity-sampling} and $S$ be a set of centers in $\mathcal{S}$. The cost vector of $\Omega$ induced by $S$ is a vector $u^S(\Omega) \in \ensuremath{\mathbb{R}}^m$ defined as follows:
   \begin{align}\label{eq: us}
   \text{For each $i \in[m]$}  \text{ we have } u^S_{i}(\Omega) = \mathbbm{1}[q_i \in  B(S)] \cdot \textnormal{cost}(q_i,S).
   \end{align}

\begin{align}\label{eq: us}
    \text{For each $i \in[m]$}  \text{ we have } u^S_{i}(\Omega) = \mathbbm{1}[q_i \in  B(S)] \cdot \textnormal{cost}(q_i,S).
    \end{align}

 \label{def: clustering-nets} Consider a fixed set $\Omega$ and let $\mathcal{T}$ be a subset of $\mathcal{S}$ (recall that $\mathcal{S}$ denotes the set of all possible $k$ centers in $\ensuremath{\mathbb{R}}^d$). For a real $\alpha \in (0,1/2]$, an $(\alpha, \mathcal{T})$ cost vector net, denoted by  $M_\alpha(\Omega, \mathcal{T})$, is a finite subset of $\ensuremath{\mathbb{R}}^m$ with the following properties. For any set of centers $S \in \mathcal{T}$ there exists some $v \in M_\alpha(\Omega, \mathcal{T})$ which $\alpha$-approximates the cost vector $u^S(\Omega)$ in the following sense: for each $i \in [m]$,
\begin{enumerate}
    \item If $q_i \in  B(S)$ then \[|v_i - u^S_i(\Omega)| = |v_i - \textnormal{cost}(q_i, S)|   \leq \alpha \cdot \textnormal{err}(q_i,S),\] where  for any $p \in P$ and $S \in \mathcal{S}$,
        \[\textnormal{err}(p,S) := \left( \sqrt{\textnormal{cost}(p,S)\textnormal{cost}(p,A)} + \sqrt{\textnormal{cost}(p,S) \Delta_{p} } + \textnormal{cost}(p,A) + \Delta_{p}\right).\]
    \item If $q_i \notin B(S)$ then $v_i = 0$ . Note that $u^S_i(\Omega) = 0$ by definition (see \eqref{eq: us}).
\end{enumerate}

 \label{def: interaction} Let $S \in \mathcal{S}$ be a set of $k$ centers. For a center $x \in S$, we say that a cluster $C_j$ in $B(S)$ \textbf{\emph{interacts}} with $x$ if both the following conditions hold:

\begin{description}
	\item{\textbf{$P_1$}: \textbf{(Point $x$ is outside average cost ball of $C_j$).}} We have  $\textnormal{cost}(a_j,x) \geq 32 \Delta_j$.
	\item{\textbf{$P_2$}: \textbf{(Point $x$ is an approximate nearest center to $a_j$).}} We have $\textnormal{cost}(a_j,x) \leq 16 \textnormal{cost}(a_j,S)$.
\end{description}

\begin{align}\label{eq: bvwr}
