\label{def: event-E}
	The event $\mathcal E$ occurs iff $\Omega$ satisfies the following properties:
	\begin{description}
		\item[$P_1$: (Cluster Size Preservation)] \label{item: event-e-1}   For each cluster $C_j$, we have \[\sum_{q\in \Omega \cap C_j}w_q \in  [(1- \ensuremath{\varepsilon})|C_j|,(1+\ensuremath{\varepsilon})|C_j|].\]
	\item[$P_2$: (Ring Size Preservation)] \label{item: event-e-2}  For each $j \in [k]$ and $0 \leq \ell \leq \ell_{max}+1$ the set $R_j(\ell)$ satisfies, \[\sum_{q\in \Omega \cap R_j(\ell)}w_q \leq |C_j|/2^{\ell-1}.\]
    \item[$P_3$: (Cluster Cost Preservation)] For each cluster $C_j$, $\textnormal{cost}_\Omega(C_j, A) = (1 \pm \ensuremath{\varepsilon}) \textnormal{cost}(C_j, A)$.

	\end{description}

