Recall that $X^{S,h}$ is given by the following expression:
\begin{align*}
X^{S,h} :={}& \frac{\sum_{i \in [m]}g_i w_{q_i} (\uq{S,h}{i} - \uq{S,h-1}{i})}{\textnormal{cost}(P,S)}.
\end{align*}
Since $X^{S,h}$ is a sum of independent centered Gaussians (using \Cref{fact: gaussian}), it is also a centered Gaussian with variance: 
\begin{align}\label{eq: var-0}
    &\mathrm{Var}[X^{S,h}] = (1/\textnormal{cost}(P,S))^2 \cdot \sum_{i \in [m]}  w_{q_i}^2 (u_i^{S, h} -u_i^{S, h-1})^2 .
\end{align}
Recall that the net vector $u^{S,h}$ is an $m$-dimensional vector whose entries approximate the cost of points in $B(S) \cap \Omega$ with respect to $S$ (see \Cref{def: clustering-nets}) where $B(S)$ is the set of clusters in band $b$ and type $t$. It follows from the definition of $u^{S,h}$ that,
\begin{enumerate}[(i)]
    \item If $q_i \in B(S)$ then, 
    $$|u_i^{S,h} - u_i^{S,h-1}| \leq |u_i^{S,h} - u_i^{S}| + |u_i^{S,h-1} - u_i^{S}| \leq 2^{-h} \textnormal{err}(q_i, S) + 2^{-(h-1)} \textnormal{err}(q_i, S)\lesssim 2^{-h} \textnormal{err}(q_i, S).$$
    \item If $q_i \notin B(S)$ then $u_i^{S,h} = u_{i}^{S,h-1} = 0$.
\end{enumerate}  Using this in \eqref{eq: var-0}, we get,
\begin{align}\label{eq: var-1}
    \mathrm{Var}[X^{S,h}]&\lesssim (1/\textnormal{cost}(P,S))^2 \cdot 2^{-2h} \cdot   \sum_{q \in B(S) \cap \Omega } w_q^2 \textnormal{err}(q,S)^2.
\end{align}
We now show that $\sum_{q \in B(S) \cap \Omega} w_q^2 \textnormal{err}(q,S)^2 \lesssim (\textnormal{cost}(P,A) \cdot \textnormal{cost}(P,S))/m$. This, together with \eqref{eq: var-1}, will then complete the proof of the lemma.  By the definition of $\textnormal{err}(q,S)$ (\Cref{def: clustering-nets}) we have $\textnormal{err}(q,S)^2 \lesssim \textnormal{cost}(q,S) ( \textnormal{cost}(q,A) + \Delta_q) + \textnormal{cost}(q,A)^2 + \Delta_q^2$. By \Cref{lem: weight-bound}, we also have $w_q \textnormal{cost}(q,A) \lesssim \textnormal{cost}(P,A)/m$ and $w_q \Delta_q \lesssim \textnormal{cost}(P,A)/m$. These equations imply that
\begin{align}
\nonumber
\sum_{q \in B(S) \cap \Omega} &w_q^2 \textnormal{err}(q,S)^2 
\lesssim  (\textnormal{cost}(P,A)/m) \cdot \sum_{q \in B(S) \cap  \Omega}  w_q  (\textnormal{cost}(q,S)  + \textnormal{cost}(q,A) + \Delta_q) 
  \\
