    Let $C=\{\mu_1,\mu_2,\ldots,\mu_k\}$ be an optimal solution with induced clusters $\{C_1,\ldots,C_k\}$ and let $\Delta = \textnormal{cost}(P,C)$. We claim that $C$, where $\mu_i$ is weighted by $|C_i|$ is the desired coreset.

    Consider some solution $S$. We first observe that if the points in $C_i$ are served by a single center in $s_i\in S$, then $\textnormal{cost}(C_i,s_i) = \textnormal{cost}(C_i,\mu_i) + |C_i|\textnormal{cost}(\mu_i,s_i)$ due to Lemma \ref{lem: centroid-fact}. Therefore, for any solution $S$ where each cluster is served by a single center, the cost is exactly preserved.

    Next, suppose that some cluster $C_i$ is served by at least two centers $s,s'\in S$. Then there must exist two clusters $C_a$ and $C_b$ that are served by the same center $s''$.
    For any cluster $C_i$, we have
    \begin{align*}
& \left\vert \textnormal{cost}(C_i,S) - (|C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(C_i, \mu_i))  \right\vert =        \bigg\vert \sum_{p\in C_i} \textnormal{cost}(p,S) - (\textnormal{cost}(\mu_i,S) + \textnormal{cost}(p,\mu_i)) \bigg\vert\\
&\leq   \sum_{p\in C_i} \varepsilon/2\cdot \textnormal{cost}(p,S) + (8/\varepsilon)\cdot \textnormal{cost}(p,\mu_i) = \varepsilon/2\cdot \textnormal{cost}(C_i,S) + (8/\varepsilon)\cdot \textnormal{cost}(C_i,C).
    \end{align*}
Summed over all clusters, this ensures 
\begin{equation}
    \label{eq:non_input_cost_diff}
    | \textnormal{cost}(P,S) - (\sum_i |C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(P, C))  | \leq \varepsilon/2\cdot \textnormal{cost}(P,S) + (8/\varepsilon)\cdot \ensuremath{\mathsf{OPT}}_k.
\end{equation}
We use the stability property to bound $\ensuremath{\mathsf{OPT}}_k$.
Without loss of generality, assume that $\|\mu_a - s''\| \leq \|\mu_b-s''\|$.
Combined with the properties of $\beta$-stable instances ( \Cref{lem: approxstability}), this ensures $\textnormal{cost}(\mu_b,S) > \textnormal{cost}(\mu_b,\mu_a)/4 \geq \beta\cdot OPT_k/(8|C_b|)$. 
Therefore, we get:
\begin{align*}
    \ensuremath{\mathsf{OPT}}_k &\leq  8 |C_b|\textnormal{cost}(\mu_b, S)/\beta
    \leq (\ensuremath{\varepsilon}^2/64) \cdot (\sum_i |C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(P, C))\\
    &\leq  (\ensuremath{\varepsilon}^2/64) \big(\textnormal{cost}(P, S) + \big\vert \textnormal{cost}(P,S) - \big(\sum_i |C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(P, C)\big)  \big\vert\big).
\end{align*}
 Plugging this into \eqref{eq:non_input_cost_diff} and rearranging gives the result.

\begin{align*}
& \left\vert \textnormal{cost}(C_i,S) - (|C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(C_i, \mu_i))  \right\vert =        \bigg\vert \sum_{p\in C_i} \textnormal{cost}(p,S) - (\textnormal{cost}(\mu_i,S) + \textnormal{cost}(p,\mu_i)) \bigg\vert\\
&\leq   \sum_{p\in C_i} \varepsilon/2\cdot \textnormal{cost}(p,S) + (8/\varepsilon)\cdot \textnormal{cost}(p,\mu_i) = \varepsilon/2\cdot \textnormal{cost}(C_i,S) + (8/\varepsilon)\cdot \textnormal{cost}(C_i,C).
    \end{align*}

\begin{equation}
    \label{eq:non_input_cost_diff}
    | \textnormal{cost}(P,S) - (\sum_i |C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(P, C))  | \leq \varepsilon/2\cdot \textnormal{cost}(P,S) + (8/\varepsilon)\cdot \ensuremath{\mathsf{OPT}}_k.
\end{equation}

\begin{align*}
    \ensuremath{\mathsf{OPT}}_k &\leq  8 |C_b|\textnormal{cost}(\mu_b, S)/\beta
    \leq (\ensuremath{\varepsilon}^2/64) \cdot (\sum_i |C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(P, C))\\
    &\leq  (\ensuremath{\varepsilon}^2/64) \big(\textnormal{cost}(P, S) + \big\vert \textnormal{cost}(P,S) - \big(\sum_i |C_i|\textnormal{cost}(\mu_i,S) + \textnormal{cost}(P, C)\big)  \big\vert\big).
