Let $p$ be a point in ring $\ell$ where $0 \leq \ell \leq l_\ensuremath{\textnormal{\texttt{max}}}$. By an application of the approximate triangle inequality  (\Cref{item: tri-2} of \Cref{fact: triangle}) and the fact that $\textnormal{cost}(p, a_j) \ll \textnormal{cost}(a_j, S)$,
\begin{align}\label{eq: reuse-2}
|\textnormal{cost}(p,S) - \textnormal{cost}(a_j,S)| \leq 2 \sqrt{ \textnormal{cost}(p,a_j)\textnormal{cost}(a_j,S)} + \textnormal{cost}(p,a_j) 
\lesssim  \sqrt{\textnormal{cost}(p,a_j)\textnormal{cost}(a_j,S)}.
\end{align}
Since $p$ is in $R_j(\ell)$ and $C_j$ is far from $S$ we obtain $\textnormal{cost}(p,a_j) \leq 2^{\ell+1} \Delta_j \leq 2^{\ell+1} \ensuremath{\varepsilon}^{2} \textnormal{cost}(a_j,S)$. Plugging this into  \Cref{eq: reuse-2} gives 
\begin{align}
\label{eq: reuse-3}
|\textnormal{cost}(p,S) - \textnormal{cost}(a_j,S)| \lesssim 2^{\ell/2} \ensuremath{\varepsilon} \textnormal{cost}(a_j,S).
\end{align}
Using this inequality and the fact that $|R_j(\ell)|$ is at most $|C_j|/2^{\ell}$ (by Markov's inequality), we get
\begin{align*}
    \sum_{\ell = 0}^{l_\ensuremath{\textnormal{\texttt{max}}}}\sum_{p \in R_j(\ell)} |\textnormal{cost}(p,S) - \textnormal{cost}(a_j,S)| \lesssim \sum_{\ell = 0}^{l_\ensuremath{\textnormal{\texttt{max}}}} \frac{|C_j|}{2^\ell} \cdot 2^{\ell/2} \ensuremath{\varepsilon} \textnormal{cost}(a_j,S)
    \lesssim \ensuremath{\varepsilon}|C_j| \textnormal{cost}(a_j,S). 
\end{align*}

Combined with the bound on $R_j(l_\ensuremath{\textnormal{\texttt{max}}}+1)$, we get:
\begin{align}
\notag
    \text{Term 1} &= |\textnormal{cost}(C_j,S) - |C_j| \cdot \textnormal{cost}(a_j,S)| \lesssim \ensuremath{\varepsilon} \textnormal{cost}(C_j,S) + \ensuremath{\varepsilon}|C_j| \textnormal{cost}(a_j,S)\\ 
    \label{eq:term1}
    &\leq \ensuremath{\varepsilon} \textnormal{cost}(C_j, S) + \ensuremath{\varepsilon} (\textnormal{cost}(C_j, S) + |\textnormal{cost}(C_j,S) - |C_j| \cdot \textnormal{cost}(a_j,S)|).
\end{align}
Rearranging, this implies $\text{Term 1} \lesssim \ensuremath{\varepsilon} \,\textnormal{cost}(C_j, S)$, as desired.
\paragraph{Bounding term 2.} This proof will be very similar to the previous one, relying on properties for event $\mathcal E$ to show the weight of each cluster is preserved in $\Omega$.

  For $\ell$ in range $0 \leq \ell \leq \ell_{max} +1$, let $W_\ell = \sum_{q \in \Omega \cap R_j(\ell)} w_q$ denote the sum of weights of coreset points in the $R_j(\ell)$ and  let $W = \sum_{\ell = 0}^{\ell_{max}+1} W_{\ell}$ be the total weight of coreset points from $C_j$. Since $ \textnormal{cost}_\Omega(C_j,S) = \sum_{\ell= 0}^{\ell_{max}+1} \textnormal{cost}_\Omega(R_j(\ell), S)$ we have,
  \begin{align}
\label{eq:frt4}
     |\textnormal{cost}_\Omega(C_j,S) - |C_j| \textnormal{cost}(a_j,S) | \leq  |\textnormal{cost}_\Omega(C_j,S) - W \textnormal{cost}(a_j,S) | + |(W - |C_j|)\cdot \textnormal{cost}(a_j,S) |
\end{align} 
If event $\mathcal E$ holds, it follows that $|W - |C_j|| \leq \ensuremath{\varepsilon} |C_j|$ and by the same reasoning as \Cref{eq:term1} that the second term of \Cref{eq:frt4} is $O(\ensuremath{\varepsilon}\, \textnormal{cost}(C_j, S) + \ensuremath{\varepsilon} \text{(Term 1)})$. It now remains to bound the first term. 
\[  |\textnormal{cost}_\Omega(C_j,S) - W \textnormal{cost}(a_j,S)| \leq \sum_{\ell = 0}^{\ell_{max}+1} |\textnormal{cost}_\Omega(R_j(\ell),S) -W_\ell \textnormal{cost}(a_j,S)|. \]
For $0 \leq \ell \leq \ell_{max}$, the event $\mathcal{E}$ and Markov's inequality ensure that $W_\ell \lesssim |C_j|/2^\ell$. Therefore, a similar calculation as in \eqref{eq: reuse-3} shows that 

\begin{flalign}\notag
&|\textnormal{cost}_\Omega(R_j(\ell),S) -W_\ell\, \textnormal{cost}(a_j,S)| = O(W_\ell \cdot \ensuremath{\varepsilon} 2^{\ell/2}\, \textnormal{cost}(a_j,S))\\
\label{eq: fake2}
& = O(|C_j|/2^\ell \cdot \ensuremath{\varepsilon} 2^{\ell/2} \,\textnormal{cost}(a_j,S))= O(\ensuremath{\varepsilon} 2^{-\ell/2} |C_j|\, \textnormal{cost}(a_j,S)) = O(\ensuremath{\varepsilon} 2^{-\ell/2}\, \textnormal{cost}(C_j,S)).
\end{flalign}
Finally, we also get, for $\ell = \ell_{max}+1$
\begin{flalign}\label{eq: fake3}
\begin{split}
&|\textnormal{cost}_\Omega(R_j(\ell_{max}+1),S) -W_{\ell_{max}+1}
\cdot \textnormal{cost}(a_j,S)| \leq \sum_{q \in \Omega \cap R_j(\ell_{max}+1)} |w_q \, \textnormal{cost}(q,S) - w_q\, \textnormal{cost}(a_j,S)|  \\& \leq \sum_{q \in \Omega \cap R_j(\ell_{max}+1)} w_q \, \textnormal{cost}(q,S) + w_q\,  \textnormal{cost}(a_j,S) \overset{(i)}{\leq} \sum_{q \in \Omega \cap R_j(\ell_{max}+1)}  (2w_q\,\textnormal{cost}(q,a_j) + 3w_q\,\textnormal{cost}(a_j,S))\\
&\overset{(ii)}{\leq} 2\textnormal{cost}_\Omega(C_j,A) + 6\ensuremath{\varepsilon} |C_j|\, \textnormal{cost}(a_j,S)
\overset{(iii)}{\leq} O(\textnormal{cost}(C_j,A)) + O(\ensuremath{\varepsilon}\,\textnormal{cost}(C_j,S)) = O(\ensuremath{\varepsilon} \,\textnormal{cost}(C_j,S)),
\end{split}
\end{flalign}
where step $(i)$ uses \Cref{fact: triangle}, step $(ii)$ uses the bound ${W_{\ell_{max}+1} \leq 2\ensuremath{\varepsilon}|C_j|}$ which holds whenever event $\mathcal{E}$ occurs.
Step $(iii)$ also follows by the third property of event $\mathcal{E}$.

Summing  \eqref{eq: fake2} and \eqref{eq: fake3} gives that Term 2 $\lesssim \ensuremath{\varepsilon}\, \textnormal{cost}(C_j, S)$, which concludes the proof.

