\label{def: single-center-net}
    Let $\alpha \in (0,1/2]$, $j \in [k]$ and $\mathcal{T}$ be the set of centers with signature $(N_1, \ldots, N_k)$. An $(\alpha, \mathcal{T},j)$-net is a set of vectors $M_{\alpha,j}$ which for each $S \in \mathcal{T}$ contains a vector $y$ that approximates the costs of points in $\Omega$ to the $j$-th center $x_j$ of $S$ as follows. For each $q_i \in B(S) \cap \Omega$, 
	\begin{enumerate}[(a)]
            \item \label{item: scn-item1} $ y_i \geq \textnormal{cost}(q_i,S) - \alpha \cdot \textnormal{err}(q_i,S)$ where $\textnormal{err}(\cdot, \cdot)$ is as defined in \Cref{def: clustering-nets}.
		\item  If $\textnormal{cost}(q_i,S) = \textnormal{cost}(q_i, x_j)$ then we further have $y_{i} \leq \textnormal{cost}(q_i,S) + \alpha \cdot \textnormal{err}(q_i,S)$ 
	\end{enumerate}

\begin{align*}
    |M_{\alpha}| = 2^k \cdot |M'_\alpha| = 2^k \cdot  \Pi_{i \in [k]} |M_{\alpha,i}| = \exp(O(\min(k2^t \alpha^{-2}, N + k \alpha^{-2}) \cdot \log(k \ensuremath{\varepsilon}^{-1} \alpha^{-1}))).
\end{align*}

For each $q \in \Omega$, consider the $d$-dimensional ball of radius $R_q$ centered at this point. Let $D(q)$ be an $(\alpha R_q)$-net of this ball (as defined in \Cref{lem: eps-net}).  By \Cref{lem: eps-net}, we have that $|D(q)| \leq (3/\alpha)^d$ and that the set $D(\Omega) = \bigcup_{q' \in \Omega} D(q')$  has at most $m (3/\alpha)^d$ points.

For $x' \in D(\Omega)$, define the cost vector $y(x') \in \ensuremath{\mathbb{R}}^m$ as follows: for $i \in [m]$ set $y_i(x') = \textnormal{cost}(q_i, x')$. Let $N_\alpha$ be the set of all such vectors. Note that $N_\alpha$ is of the claimed size.

Let $x$ be a point in $\ensuremath{\mathbb{R}}^d$ and $x'$ be the point in  $D(\Omega)$ nearest to $x$. We show that $y(x') \in N_\alpha$ satisfies both \Cref{item: net-cond-1} and \Cref{item: net-cond-2} for the point $x$. 

\textbf{Proof of \Cref{item: net-cond-1}.} If $q_i \in \Omega$ is a point satisfying $\textnormal{cost}(q_i,x) \leq R_{q_i}^2$ then we have by our choice of $x'$ that $\norm{x - x'} \leq \alpha R_{q_i}$. By triangle inequality (\Cref{fact: triangle}), 
\begin{align*}
    |\textnormal{cost}(q_i,x) - y_i(x')| &= |\textnormal{cost}(q_i,x) - \textnormal{cost}(q_i,x')| 
            \leq 2\sqrt{\textnormal{cost}(q_i,x) \textnormal{cost}(x,x')} + \textnormal{cost}(x,x') \\
            &\leq 2 \sqrt{R_{q_i}^2 \cdot \alpha^2 R_{q_i}^2} + \alpha^2 R_{q_i}^2 \leq 3\alpha R_{q_i}^2.
\end{align*}

\textbf{Proof of \Cref{item: net-cond-2}.} Suppose that $q_i \in \Omega$ is a point with $\textnormal{cost}(q_i,x)> R_{q_i}^2$. We now want to show that $y_i(x')$ does not underestimate the cost of $q_i$ by too much.   Consider the ball of radius $R_{q_i}$ centered at $q_i$ and let $p$ be the point in this ball nearest to $x$. Clearly, $D(\Omega)$ contains a point within distance $(\alpha R_{q_i})$ of $p$. Therefore, we have $\norm{x-x'} \leq \norm{p-x} + \alpha R_{q_i}$. By triangle inequality,
\begin{align}
                \norm{{q_i}-x'} &\,\,\geq \,\, \norm{{q_i}-x} - \norm{x - x'} \,\,\geq\,\,\norm{{q_i} - x} - \norm{p-x} - \alpha R_{q_i} \,\,= \,\,R_{q_i} - \alpha R_{q_i} 
\end{align}
where the last line uses that ${q_i},p,x$ are collinear. Therefore, $y_i(x') = \textnormal{cost}({q_i},x') \geq (R_{q_i} - \alpha R_{q_i})^2 \geq R_{q_i}^2 - 2\alpha R_{q_i}^2$. The result follows by rescaling $\alpha$.

\begin{align*}
    |\textnormal{cost}(q_i,x) - y_i(x')| &= |\textnormal{cost}(q_i,x) - \textnormal{cost}(q_i,x')| 
            \leq 2\sqrt{\textnormal{cost}(q_i,x) \textnormal{cost}(x,x')} + \textnormal{cost}(x,x') \\
            &\leq 2 \sqrt{R_{q_i}^2 \cdot \alpha^2 R_{q_i}^2} + \alpha^2 R_{q_i}^2 \leq 3\alpha R_{q_i}^2.
\end{align*}

