\begin{equation}
\label{eq:kmediannet}
|d^2(p,s)-d^2(p,s')|\leq \varepsilon\cdot \sqrt{d^2(p,S)\cdot d^2(p,A)}    
\end{equation}

The proof of this bound is similar to \Cref{lem: easy-var} with the only difference that we need to account for the finer nets. We have,
\begin{align}\label{eq: var-1-kmedian}
    \mathrm{Var}[X^{S,h}]&\lesssim (1/\textnormal{cost}(P,S))^2 2^{-2h}  \sum_{q \in B(S) \cap \Omega } w_q^2 \textnormal{cost}(q,A)^2.
\end{align}
Using the fact that $w_q \textnormal{cost}(q,A) \lesssim \textnormal{cost}(P,A)/m \lesssim \textnormal{cost}(P,S)/m$ (due to the bounds on the weight) together with $2^t \sum_{q \in B(S) \cap \Omega }  w_{q} \textnormal{cost}(q,A) \lesssim  \textnormal{cost}(P,S)$ in \Cref{eq: var-1-kmedian} leads to the claimed bound.\qedhere

\begin{align}\label{eq: var-1-kmedian}
    \mathrm{Var}[X^{S,h}]&\lesssim (1/\textnormal{cost}(P,S))^2 2^{-2h}  \sum_{q \in B(S) \cap \Omega } w_q^2 \textnormal{cost}(q,A)^2.
\end{align}

\begin{align}\label{eq: combine-variance}
    \mathrm{Var}[X^{S,h}] \lesssim  \min(2^{-t}, k^2 2^{-(2t+r)}) \cdot 2^{-2h} m^{-1}.
\end{align}

\begin{align}\label{eq: combine-net}
    \log |M_{2^{-h}}| \lesssim  \min(k2^{2t}, 2^{r}) \cdot 2^{2h} \log(k\ensuremath{\varepsilon}^{-1}).
\end{align}

\begin{align}
    \Gamma  &\lesssim \sqrt{\min(k2^{t}, k^2 2^{-2t}) \cdot \log(k \ensuremath{\varepsilon}^{-1})m^{-1}} \label{eq: interm-combine-kmedian}\\
    &\lesssim \sqrt{k^{4/3} \cdot \log(k \ensuremath{\varepsilon}^{-1})m^{-1}}.
\end{align}
